/* ─── Reset & Base ─────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-bg:        #f8f7f4;
  --clr-surface:   #ffffff;
  --clr-ink:       #111111;
  --clr-ink-muted: #6b6b6b;
  --clr-accent:    #d4452a;
  --clr-accent-lt: #fdf0ed;
  --clr-border:    #e5e3de;
  --clr-badge:     #1a8f5a;
  --ff-sans: 'Inter', system-ui, sans-serif;
  --ff-serif: 'Playfair Display', Georgia, serif;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-card: 0 2px 12px rgba(0,0,0,.07);
  --shadow-hover: 0 8px 32px rgba(0,0,0,.13);
  --transition: .22s cubic-bezier(.4,0,.2,1);
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--ff-sans);
  background: var(--clr-bg);
  color: var(--clr-ink);
  line-height: 1.6;
  font-size: 15px;
}

img { display: block; max-width: 100%; }
a  { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font: inherit; }
ul { list-style: none; }

.sr-only {
  position: absolute; width: 1px; height: 1px;
  overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap;
}

/* ─── Layout helpers ───────────────────────────────────────── */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 32px;
  gap: 16px;
}

.section-title {
  font-family: var(--ff-serif);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  line-height: 1.2;
}

.section-subtitle {
  color: var(--clr-ink-muted);
  font-size: 0.9rem;
  margin-top: 4px;
}

.view-all {
  white-space: nowrap;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--clr-accent);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: gap var(--transition);
}
.view-all:hover { gap: 8px; }
.view-all::after { content: '→'; }

/* ─── Announcement Bar ─────────────────────────────────────── */
#announcement-bar {
  background: var(--clr-ink);
  color: #fff;
  text-align: center;
  padding: 10px 24px;
  font-size: 0.82rem;
  letter-spacing: .04em;
}

#announcement-bar span { color: var(--clr-accent); font-weight: 600; }

/* ─── Header / Nav ─────────────────────────────────────────── */
#site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--clr-border);
  transition: box-shadow var(--transition);
}

#site-header.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,.08); }

.header-inner {
  display: flex;
  align-items: center;
  height: 68px;
  gap: 32px;
}

.logo {
  font-family: var(--ff-serif);
  font-size: 1.55rem;
  font-weight: 700;
  letter-spacing: -.02em;
  flex-shrink: 0;
}

.logo em { color: var(--clr-accent); font-style: normal; }

.primary-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.primary-nav a {
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--clr-ink-muted);
  transition: color var(--transition), background var(--transition);
}

.primary-nav a:hover,
.primary-nav a.active {
  color: var(--clr-ink);
  background: var(--clr-bg);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

.icon-btn {
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  display: grid; place-items: center;
  color: var(--clr-ink-muted);
  transition: color var(--transition), background var(--transition);
  position: relative;
}

.icon-btn:hover { color: var(--clr-ink); background: var(--clr-bg); }

.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  width: 17px; height: 17px;
  border-radius: 50%;
  background: var(--clr-accent);
  color: #fff;
  font-size: 0.65rem;
  font-weight: 700;
  display: grid; place-items: center;
  line-height: 1;
}

.search-form {
  display: flex;
  align-items: center;
  background: var(--clr-bg);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-sm);
  padding: 0 12px;
  height: 38px;
  gap: 8px;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.search-form:focus-within {
  border-color: var(--clr-ink);
  box-shadow: 0 0 0 3px rgba(17,17,17,.07);
}

.search-form input {
  border: none;
  background: transparent;
  outline: none;
  font: inherit;
  font-size: 0.88rem;
  width: 200px;
  color: var(--clr-ink);
}

.search-form input::placeholder { color: var(--clr-ink-muted); }

/* ─── Hero ─────────────────────────────────────────────────── */
#hero {
  padding: 64px 0 80px;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--clr-accent-lt);
  color: var(--clr-accent);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: 999px;
  margin-bottom: 20px;
}

.hero-title {
  font-family: var(--ff-serif);
  font-size: clamp(2.4rem, 5vw, 3.8rem);
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 20px;
  letter-spacing: -.02em;
}

.hero-title mark {
  background: none;
  color: var(--clr-accent);
}

.hero-body {
  color: var(--clr-ink-muted);
  font-size: 1.05rem;
  max-width: 460px;
  margin-bottom: 36px;
}

.hero-cta-group {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--clr-ink);
  color: #fff;
  padding: 13px 28px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 0.92rem;
  transition: background var(--transition), transform var(--transition);
}

.btn-primary:hover { background: #2a2a2a; transform: translateY(-1px); }

.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--clr-ink);
  font-weight: 600;
  font-size: 0.92rem;
  border-bottom: 1.5px solid var(--clr-ink);
  padding-bottom: 2px;
  transition: color var(--transition), border-color var(--transition);
}

.btn-ghost:hover { color: var(--clr-accent); border-color: var(--clr-accent); }

.hero-stats {
  display: flex;
  gap: 32px;
  margin-top: 48px;
}

.stat-item strong {
  display: block;
  font-size: 1.55rem;
  font-weight: 800;
  letter-spacing: -.02em;
}

.stat-item span {
  font-size: 0.8rem;
  color: var(--clr-ink-muted);
}

.hero-visual {
  position: relative;
}

.hero-image-wrap {
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 4/5;
  background: linear-gradient(135deg, #e8e3d8 0%, #d4cfc4 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-image-wrap svg { opacity: .18; }

.hero-badge {
  position: absolute;
  bottom: 32px;
  left: -24px;
  background: var(--clr-surface);
  border-radius: var(--radius-md);
  padding: 16px 20px;
  box-shadow: var(--shadow-hover);
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 220px;
}

.hero-badge-icon {
  width: 44px; height: 44px;
  border-radius: var(--radius-sm);
  background: var(--clr-accent-lt);
  display: grid; place-items: center;
  color: var(--clr-accent);
  flex-shrink: 0;
}

.hero-badge strong { display: block; font-size: 0.88rem; }
.hero-badge span   { font-size: 0.78rem; color: var(--clr-ink-muted); }

.hero-tag {
  position: absolute;
  top: 24px;
  right: -16px;
  background: var(--clr-badge);
  color: #fff;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 8px 16px;
  border-radius: 999px;
}

/* ─── Category Strip ───────────────────────────────────────── */
#categories {
  padding: 0 0 64px;
}

.category-strip {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: none;
}

.category-strip::-webkit-scrollbar { display: none; }

.category-pill {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: 999px;
  padding: 10px 20px 10px 10px;
  white-space: nowrap;
  font-size: 0.88rem;
  font-weight: 500;
  transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
  cursor: pointer;
}

.category-pill:hover {
  border-color: var(--clr-ink);
  box-shadow: var(--shadow-card);
  transform: translateY(-2px);
}

.category-pill.active {
  background: var(--clr-ink);
  color: #fff;
  border-color: var(--clr-ink);
}

.cat-icon {
  width: 36px; height: 36px;
  border-radius: 50%;
  display: grid; place-items: center;
  font-size: 1.1rem;
  background: var(--clr-bg);
}

.category-pill.active .cat-icon { background: rgba(255,255,255,.15); }

/* ─── Featured Products ────────────────────────────────────── */
#featured-products { padding: 0 0 80px; }

.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}

.product-card {
  background: var(--clr-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--clr-border);
  transition: box-shadow var(--transition), transform var(--transition);
  cursor: pointer;
}

.product-card:hover {
  box-shadow: var(--shadow-hover);
  transform: translateY(-4px);
}

.product-image {
  aspect-ratio: 1;
  position: relative;
  overflow: hidden;
}

.product-image-bg {
  width: 100%; height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  transition: transform var(--transition);
}

.product-card:hover .product-image-bg { transform: scale(1.06); }

.product-actions {
  position: absolute;
  top: 12px; right: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  opacity: 0;
  transform: translateX(8px);
  transition: opacity var(--transition), transform var(--transition);
}

.product-card:hover .product-actions {
  opacity: 1;
  transform: translateX(0);
}

.action-btn {
  width: 36px; height: 36px;
  border-radius: var(--radius-sm);
  background: var(--clr-surface);
  display: grid; place-items: center;
  box-shadow: 0 2px 8px rgba(0,0,0,.12);
  color: var(--clr-ink-muted);
  transition: color var(--transition), background var(--transition);
}

.action-btn:hover { color: var(--clr-accent); background: var(--clr-accent-lt); }
.action-btn.liked  { color: var(--clr-accent); }

.product-badge {
  position: absolute;
  top: 12px; left: 12px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 999px;
}

.badge-new     { background: var(--clr-ink); color: #fff; }
.badge-sale    { background: var(--clr-accent); color: #fff; }
.badge-popular { background: var(--clr-badge); color: #fff; }

.product-body { padding: 16px; }

.product-brand {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--clr-ink-muted);
  margin-bottom: 4px;
}

.product-name {
  font-weight: 600;
  font-size: 0.95rem;
  margin-bottom: 8px;
  line-height: 1.3;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 12px;
}

.stars { color: #f59e0b; font-size: 0.8rem; letter-spacing: .05em; }
.rating-count { font-size: 0.78rem; color: var(--clr-ink-muted); }

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.product-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.price-current { font-size: 1.05rem; font-weight: 700; }
.price-was     { font-size: 0.85rem; color: var(--clr-ink-muted); text-decoration: line-through; }

.add-to-cart {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--clr-ink);
  color: #fff;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 0.82rem;
  font-weight: 600;
  transition: background var(--transition), transform var(--transition);
}

.add-to-cart:hover { background: var(--clr-accent); transform: scale(1.02); }

/* ─── Deals Banner ─────────────────────────────────────────── */
#deals { padding: 0 0 80px; }

.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 16px;
}

.deal-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
  cursor: pointer;
  transition: transform var(--transition), box-shadow var(--transition);
}

.deal-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-hover); }

.deal-card-inner {
  padding: 36px 32px;
  height: 100%;
  min-height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  background-size: cover;
  background-position: center;
  position: relative;
}

.deal-card-inner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.6) 0%, transparent 60%);
  border-radius: inherit;
}

.deal-card:nth-child(1) .deal-card-inner { background-color: #2b2320; }
.deal-card:nth-child(2) .deal-card-inner { background-color: #1a2f1e; min-height: 180px; }
.deal-card:nth-child(3) .deal-card-inner { background-color: #1e1f2f; min-height: 180px; }

.deal-content { position: relative; z-index: 1; }

.deal-eyebrow {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: rgba(255,255,255,.65);
  margin-bottom: 6px;
}

.deal-title {
  font-family: var(--ff-serif);
  font-size: 1.35rem;
  font-weight: 700;
  color: #fff;
  line-height: 1.2;
  margin-bottom: 12px;
}

.deal-card:first-child .deal-title { font-size: 1.9rem; }

.deal-badge-wrap { display: flex; align-items: center; gap: 10px; }

.deal-discount {
  display: inline-flex;
  align-items: center;
  background: var(--clr-accent);
  color: #fff;
  font-size: 0.82rem;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 999px;
}

.deal-link {
  font-size: 0.82rem;
  font-weight: 600;
  color: rgba(255,255,255,.75);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: color var(--transition), gap var(--transition);
}

.deal-link:hover { color: #fff; gap: 8px; }
.deal-link::after { content: '→'; }

.deal-emoji {
  position: absolute;
  top: 24px; right: 24px;
  font-size: 3rem;
  opacity: .4;
  z-index: 1;
}

/* ─── Countdown Timer ──────────────────────────────────────── */
.deal-timer {
  display: flex;
  gap: 6px;
  margin-bottom: 16px;
}

.timer-unit {
  display: flex;
  flex-direction: column;
  align-items: center;
  background: rgba(255,255,255,.1);
  backdrop-filter: blur(4px);
  border-radius: var(--radius-sm);
  padding: 6px 10px;
  min-width: 48px;
}

.timer-value {
  font-size: 1.3rem;
  font-weight: 800;
  color: #fff;
  line-height: 1;
}

.timer-label {
  font-size: 0.6rem;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: rgba(255,255,255,.55);
}

/* ─── Editorial ────────────────────────────────────────────── */
#editorial { padding: 0 0 80px; }

.editorial-grid {
  display: grid;
  grid-template-columns: 3fr 2fr;
  gap: 24px;
}

.editorial-card {
  background: var(--clr-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--clr-border);
  cursor: pointer;
  transition: box-shadow var(--transition), transform var(--transition);
}

.editorial-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-3px); }

.editorial-card.featured {
  display: flex;
  flex-direction: column;
}

.editorial-image {
  aspect-ratio: 16/9;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  position: relative;
  overflow: hidden;
}

.editorial-card.featured .editorial-image { aspect-ratio: unset; flex: 1; min-height: 260px; }

.editorial-small-grid {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.editorial-card.small {
  display: grid;
  grid-template-columns: 140px 1fr;
}

.editorial-card.small .editorial-image { aspect-ratio: 1; font-size: 3rem; min-height: unset; }

.editorial-body { padding: 24px; display: flex; flex-direction: column; }

.editorial-card.small .editorial-body { padding: 16px; justify-content: center; }

.editorial-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: 10px;
}

.editorial-title {
  font-family: var(--ff-serif);
  font-size: 1.25rem;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 10px;
}

.editorial-card.small .editorial-title { font-size: 0.95rem; }

.editorial-excerpt {
  color: var(--clr-ink-muted);
  font-size: 0.88rem;
  line-height: 1.6;
  margin-bottom: 16px;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.editorial-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.78rem;
  color: var(--clr-ink-muted);
  margin-top: auto;
}

.meta-dot { width: 3px; height: 3px; border-radius: 50%; background: var(--clr-border); }

.read-more {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--clr-accent);
  margin-top: auto;
  transition: gap var(--transition);
}

.read-more:hover { gap: 8px; }
.read-more::after { content: '→'; }

/* ─── Trust Strip ──────────────────────────────────────────── */
#trust-strip { padding: 0 0 80px; }

.trust-inner {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: var(--clr-border);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.trust-item {
  background: var(--clr-surface);
  padding: 28px 24px;
  display: flex;
  align-items: center;
  gap: 16px;
}

.trust-icon {
  width: 48px; height: 48px;
  border-radius: var(--radius-sm);
  background: var(--clr-bg);
  display: grid; place-items: center;
  font-size: 1.4rem;
  flex-shrink: 0;
}

.trust-item strong { display: block; font-size: 0.9rem; font-weight: 600; }
.trust-item span   { font-size: 0.8rem; color: var(--clr-ink-muted); }

/* ─── Newsletter ───────────────────────────────────────────── */
#newsletter { padding: 0 0 96px; }

.newsletter-inner {
  background: var(--clr-ink);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 64px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  position: relative;
  overflow: hidden;
}

.newsletter-inner::before {
  content: '';
  position: absolute;
  width: 500px; height: 500px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(212,69,42,.25) 0%, transparent 70%);
  right: -100px; top: -150px;
  pointer-events: none;
}

.newsletter-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255,255,255,.08);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: 999px;
  margin-bottom: 20px;
  color: rgba(255,255,255,.7);
}

.newsletter-title {
  font-family: var(--ff-serif);
  font-size: clamp(1.6rem, 3vw, 2.2rem);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 12px;
}

.newsletter-body {
  color: rgba(255,255,255,.65);
  font-size: 0.95rem;
}

.newsletter-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.newsletter-fields {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-field label {
  font-size: 0.78rem;
  font-weight: 500;
  color: rgba(255,255,255,.55);
}

.form-field input {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.12);
  border-radius: var(--radius-sm);
  padding: 11px 14px;
  color: #fff;
  font: inherit;
  font-size: 0.9rem;
  outline: none;
  transition: border-color var(--transition);
}

.form-field input::placeholder { color: rgba(255,255,255,.3); }
.form-field input:focus { border-color: rgba(255,255,255,.35); }

.newsletter-email-wrap {
  position: relative;
}

.newsletter-email-wrap input {
  width: 100%;
  padding-right: 130px;
}

.newsletter-submit {
  position: absolute;
  right: 5px; top: 50%;
  transform: translateY(-50%);
  background: var(--clr-accent);
  color: #fff;
  padding: 7px 20px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 0.85rem;
  transition: background var(--transition);
}

.newsletter-submit:hover { background: #c23b22; }

.newsletter-consent {
  font-size: 0.75rem;
  color: rgba(255,255,255,.38);
  line-height: 1.5;
}

/* ─── Footer ───────────────────────────────────────────────── */
#site-footer {
  background: var(--clr-ink);
  color: rgba(255,255,255,.65);
  padding: 60px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand .logo {
  color: #fff;
  margin-bottom: 16px;
  display: block;
}

.footer-tagline {
  font-size: 0.88rem;
  line-height: 1.7;
  margin-bottom: 24px;
}

.social-links {
  display: flex;
  gap: 10px;
}

.social-link {
  width: 36px; height: 36px;
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,.08);
  display: grid; place-items: center;
  font-size: 0.9rem;
  color: rgba(255,255,255,.6);
  transition: background var(--transition), color var(--transition);
}

.social-link:hover { background: var(--clr-accent); color: #fff; }

.footer-col h4 {
  color: #fff;
  font-size: 0.88rem;
  font-weight: 600;
  margin-bottom: 16px;
  letter-spacing: .02em;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.footer-col a {
  font-size: 0.85rem;
  transition: color var(--transition);
}

.footer-col a:hover { color: #fff; }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding-top: 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  font-size: 0.8rem;
}

.payment-methods {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 1.2rem;
}

/* ─── Responsive ───────────────────────────────────────────── */
@media (max-width: 1024px) {
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card:first-child { grid-column: 1 / -1; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero-visual { display: none; }
  .primary-nav { display: none; }
  .search-form { display: none; }
  .deals-grid { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card.small { grid-template-columns: 1fr; }
  .editorial-card.small .editorial-image { aspect-ratio: 16/9; font-size: 4rem; }
  .trust-inner { grid-template-columns: 1fr 1fr; }
  .newsletter-inner { grid-template-columns: 1fr; padding: 40px 28px; }
  .newsletter-fields { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
}

@media (max-width: 480px) {
  .hero-stats { gap: 20px; }
  .trust-inner { grid-template-columns: 1fr; }
}

/* ─── Animations ───────────────────────────────────────────── */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(24px); }
  to   { opacity: 1; transform: translateY(0); }
}

.fade-up {
  opacity: 0;
  animation: fadeUp .5s ease forwards;
}

.fade-up-1 { animation-delay: .05s; }
.fade-up-2 { animation-delay: .15s; }
.fade-up-3 { animation-delay: .25s; }
.fade-up-4 { animation-delay: .35s; }

