*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-bg:        #f8f7f4;
  --clr-surface:   #ffffff;
  --clr-ink:       #111111;
  --clr-ink-muted: #6b6b6b;
  --clr-accent:    #d4452a;
  --clr-accent-lt: #fdf0ed;
  --clr-border:    #e5e3de;
  --clr-badge:     #1a8f5a;
  --ff-sans: 'Inter', system-ui, sans-serif;
  --ff-serif: 'Playfair Display', Georgia, serif;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-card: 0 2px 12px rgba(0,0,0,.07);
  --shadow-hover: 0 8px 32px rgba(0,0,0,.13);
  --transition: .22s cubic-bezier(.4,0,.2,1);
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--ff-sans);
  background: var(--clr-bg);
  color: var(--clr-ink);
  line-height: 1.6;
  font-size: 15px;
}

img { display: block; max-width: 100%; }
a  { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font: inherit; }
ul { list-style: none; }

.sr-only {
  position: absolute; width: 1px; height: 1px;
  overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap;
}

/* ─── Layout helpers ───────────────────────────────────────── */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 32px;
  gap: 16px;
}

.section-title {
  font-family: var(--ff-serif);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: 700;
  line-height: 1.2;
}

.section-subtitle {
  color: var(--clr-ink-muted);
  font-size: 0.9rem;
  margin-top: 4px;
}

.view-all {
  white-space: nowrap;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--clr-accent);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: gap var(--transition);
}
.view-all:hover { gap: 8px; }
.view-all::after { content: '→'; }

/* ─── Announcement Bar ─────────────────────────────────────── */
#announcement-bar {
  background: var(--clr-ink);
  color: #fff;
  text-align: center;
  padding: 10px 24px;
  font-size: 0.82rem;
  letter-spacing: .04em;
}

#announcement-bar span { color: var(--clr-accent); font-weight: 600; }

/* ─── Header / Nav ─────────────────────────────────────────── */
#site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--clr-border);
  transition: box-shadow var(--transition);
}

#site-header.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,.08); }

.header-inner {
  display: flex;
  align-items: center;
  height: 68px;
  gap: 32px;
}

.logo {
  font-family: var(--ff-serif);
  font-size: 1.55rem;
  font-weight: 700;
  letter-spacing: -.02em;
  flex-shrink: 0;
}

.logo em { color: var(--clr-accent); font-style: normal; }

.primary-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.primary-nav a {
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--clr-ink-muted);
  transition: color var(--transition), background var(--transition);
}

.primary-nav a:hover,
.primary-nav a.active {
  color: var(--clr-ink);
  background: var(--clr-bg);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

.icon-btn {
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  display: grid; place-items: center;
  color: var(--clr-ink-muted);
  transition: color var(--transition), background var(--transition);
  position: relative;
}

.icon-btn:hover { color: var(--clr-ink); background: var(--clr-bg); }

.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  width: 17px; height: 17px;
  border-radius: 50%;
  background: var(--clr-accent);
  color: #fff;
  font-size: 0.65rem;
  font-weight: 700;
  display: grid; place-items: center;
  line-height: 1;
}

.search-form {
  display: flex;
  align-items: center;
  background: var(--clr-bg);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-sm);
  padding: 0 12px;
  height: 38px;
  gap: 8px;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.search-form:focus-within {
  border-color: var(--clr-ink);
  box-shadow: 0 0 0 3px rgba(17,17,17,.07);
}

.search-form input {
  border: none;
  background: transparent;
  outline: none;
  font: inherit;
  font-size: 0.88rem;
  width: 200px;
  color: var(--clr-ink);
}

.search-form input::placeholder { color: var(--clr-ink-muted); }

/* ─── Hero ─────────────────────────────────────────────────── */
#hero {
  padding: 64px 0 80px;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--clr-accent-lt);
  color: var(--clr-accent);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: 999px;
  margin-bottom: 20px;
}

.hero-title {
  font-family: var(--ff-serif);
  font-size: clamp(2.4rem, 5vw, 3.8rem);
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 20px;
  letter-spacing: -.02em;
}

.hero-title mark {
  background: none;
  color: var(--clr-accent);
}

.hero-body {
  color: var(--clr-ink-muted);
  font-size: 1.05rem;
  max-width: 460px;
  margin-bottom: 36px;
}

.hero-cta-group {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--clr-ink);
  color: #fff;
  padding: 13px 28px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 0.92rem;
  transition: background var(--transition), transform var(--transition);
}

.btn-primary:hover { background: #2a2a2a; transform: translateY(-1px); }

.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--clr-ink);
  font-weight: 600;
  font-size: 0.92rem;
  border-bottom: 1.5px solid var(--clr-ink);
  padding-bottom: 2px;
  transition: color var(--transition), border-color var(--transition);
}

.btn-ghost:hover { color: var(--clr-accent); border-color: var(--clr-accent); }

.hero-stats {
  display: flex;
  gap: 32px;
  margin-top: 48px;
}

.stat-item strong {
  display: block;
  font-size: 1.55rem;
  font-weight: 800;
  letter-spacing: -.02em;
}

.stat-item span {
  font-size: 0.8rem;
  color: var(--clr-ink-muted);
}

.hero-visual {
  position: relative;
}

.hero-image-wrap {
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 4/5;
  background: linear-gradient(135deg, #e8e3d8 0%, #d4cfc4 100%);
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-image-wrap svg { opacity: .18; }

.hero-badge {
  position: absolute;
  bottom: 32px;
  left: -24px;
  background: var(--clr-surface);
  border-radius: var(--radius-md);
  padding: 16px 20px;
  box-shadow: var(--shadow-hover);
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 220px;
}

.hero-badge-icon {
  width: 44px; height: 44px;
  border-radius: var(--radius-sm);
  background: var(--clr-accent-lt);
  display: grid; place-items: center;
  color: var(--clr-accent);
  flex-shrink: 0;
}

.hero-badge strong { display: block; font-size: 0.88rem; }
.hero-badge span   { font-size: 0.78rem; color: var(--clr-ink-muted); }

.hero-tag {
  position: absolute;
  top: 24px;
  right: -16px;
  background: var(--clr-badge);
  color: #fff;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 8px 16px;
  border-radius: 999px;
}

/* ─── Category Strip ───────────────────────────────────────── */
#categories {
  padding: 0 0 64px;
}

.category-strip {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: none;
}

.category-strip::-webkit-scrollbar { display: none; }

.category-pill {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: 999px;
  padding: 10px 20px 10px 10px;
  white-space: nowrap;
  font-size: 0.88rem;
  font-weight: 500;
  transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
  cursor: pointer;
}

.category-pill:hover {
  border-color: var(--clr-ink);
  box-shadow: var(--shadow-card);
  transform: translateY(-2px);
}

.category-pill.active {
  background: var(--clr-ink);
  color: #fff;
  border-color: var(--clr-ink);
}

.cat-icon {
  width: 36px; height: 36px;
  border-radius: 50%;
  display: grid; place-items: center;
  font-size: 1.1rem;
  background: var(--clr-bg);
}

.category-pill.active .cat-icon { background: rgba(255,255,255,.15); }

/* ─── Featured Products ────────────────────────────────────── */
#featured-products { padding: 0 0 80px; }

.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 24px;
}

.product-card {
  background: var(--clr-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--clr-border);
  transition: box-shadow var(--transition), transform var(--transition);
  cursor: pointer;
